<template><el-dialog v-model="visible" :title="(row ? t('crud.test.form.editTitle', '编辑') : t('crud.test.form.createTitle', '新增'))" width="720px"><SchemaRenderer :key="generation" ref="schemaFormRef" :schema="formSchema" :values="form" :options-request="optionsRequest" form-key="test" @change="(field, value) => { form[field] = value; changed.add(field); }" /><template #footer><el-button @click="visible=false">{{ t('crud.test.form.cancel', '取消') }}</el-button><el-button type="primary" :loading="saving" @click="submit">{{ t('crud.test.form.save', '保存') }}</el-button></template></el-dialog></template>
<script setup lang="ts">
