const visible=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)}); const form=reactive<Record<string,unknown>>({}); const changed=reactive(new Set<string>()); const schemaFormRef=ref<InstanceType<typeof SchemaRenderer>>(); const sourceSchema={"actions":[],"dataSources":[],"database":{"connection":"mysql","source":"created","table":"example_test"},"extensions":{"legacy":{"remark":"","status":1},"dependencies":{"hash":"884b6720fe8225d534e1adda7ca6553fb83b8fc77839c56eaaecf75ee5ffbb5c"}},"form":[],"key":"test","layout":[],"list":[],"model":[],"nodes":[{"children":[],"conditions":[],"dataSource":null,"database":{"columnType":"varchar(255)","comment":"","index":"none","nullable":true,"relation":{"labelField":"","multiple":false,"onDelete":"restrict","table":"","type":"none","valueField":"id"},"unsigned":false},"defaultValue":"","disabled":false,"events":[],"field":"field_1","hidden":false,"id":"node_input_1","kind":"field","layout":{"group":"","span":24},"list":{"filter":"","formatter":"","show":true,"sort":false,"width":0},"props":{"clearable":true},"title":"单行输入","type":"input","validation":[]},{"children":[],"conditions":[],"dataSource":{"kind":"static","mode":"static","options":[{"label":"张三","value":1},{"label":"李四","value":2}]},"database":{"columnType":"varchar(500)","comment":"","index":"none","nullable":true,"relation":{"labelField":"","multiple":false,"onDelete":"restrict","table":"","type":"none","valueField":"id"},"unsigned":false},"defaultValue":"","disabled":false,"events":[],"field":"field_2","hidden":false,"id":"node_mention_2","kind":"field","layout":{"group":"","span":24},"list":{"filter":"","formatter":"","show":true,"sort":false,"width":0},"props":{"rows":3,"type":"textarea"},"title":"提及输入","type":"mention","validation":[]},{"children":[],"conditions":[],"dataSource":{"kind":"static","mode":"static","options":[{"label":"选项一","value":1},{"label":"选项二","value":2}]},"database":{"columnType":"varchar(100)","comment":"","index":"n