watch(()=>[props.row,props.modelValue] as const,([row])=>{generation.value++;changed.clear();Object.keys(form).forEach(key=>delete form[key]);for(const item of valueMap)form[item.target]=row && fieldMap.some(field=>field.target===item.target && field.sensitive)?'':row?.[item.source as keyof TestModel]??defaults[item.target]??'';},{immediate:true});
async function submit(){const lock=props.lock;if(!active||saving.value||lock?.busy||!permitted(!!props.row))return;saving.value=true;if(lock)lock.busy=true;const token=generation.value;const row=props.row;try{if(!active||token!==generation.value||!props.modelValue||!permitted(!!row))return;const renderer=schemaFormRef.value;if(!renderer)return;await renderer.submit();if(!active||token!==generation.value||!props.modelValue||!permitted(!!row))return;const submitted=buildSubmissionPayload(submissionFields,form,resolveSubmissionInclude({schema_document:sourceSchema}),permission=>user.permissions.some(code=>code==='*'||code==='*:*:*'||code===permission));const payload=Object.fromEntries(fieldMap.filter(item=>Object.hasOwn(submitted,item.target)&&(!item.sensitive || !row || changed.has(item.target))).map(item=>[item.source,submitted[item.target]])) as TestModelPayload;if (row) { await testApi.update(row.id,payload); } else { await testApi.create(payload); }if(active&&token===generation.value&&props.modelValue){visible.value=false;emit('success');}}catch(reason){const response=reason&&typeof reason==='object'?reason as {data?:{fieldErrors?:Array<{path:string;message:string}>};fieldErrors?:Array<{path:string;message:string}>}:null;const errors=response?.data?.fieldErrors??response?.fieldErrors??[];if(Array.isArray(errors)&&errors.length){if(!active||token!==generation.value||!props.modelValue)return;const mapped=mapFieldErrors(errors);const normalized=Object.fromEntries(Object.entries(mapped).map(([key,message])=>[valueMap.find(item=>item.target===key)?.target??valueMap.find(item=>item.source===key)?.target??key,message]));await schemaFormRef.value?.setFieldErrors(normalized);return;}throw reason;}finally{saving.value=false;if(lock)lock.busy=false;}}
